import math

def canMeasureWater(x: int, y: int, z: int) -> bool:
    if z < 0:
        return False
    if z == 0:
        return True
    if x + y < z:
        return False
    if x == 0 and y == 0:
        return False
    if x == 0:
        return z % y == 0
    if y == 0:
        return z % x == 0
    return z % math.gcd(x, y) == 0
